// Which demo user is this email for? Gmail plus-addressing: your.name+<alias>@gmail.com
const USERS = {
  "finance": { account_id: "DE00****0000", account_holder: "Anna Beispiel" },
  "":        { account_id: "DE00****0000", account_holder: "Anna Beispiel" },
  "ben":     { account_id: "DE33****0033", account_holder: "Ben Neumann" },
  "clara":   { account_id: "DE44****0044", account_holder: "Clara Weber" },
};
const recipients = [
  $json.to?.text, ...($json.to?.value || []).map(v => v.address),
  $json.headers?.["delivered-to"], $json.headers?.to
].filter(Boolean).join(" ").toLowerCase();
const m = recipients.match(/\+([a-z0-9]+)@/);
const alias = m ? m[1] : "";
const user = USERS[alias];
if (!user) return null;   // unknown alias: skip, never guess the user

const text = String($json.text || $json.snippet || "");
const email = {
  email_id: $json.id,
  from: $json.from?.text || $json.from?.value?.[0]?.address || "",
  date: $json.date ? String($json.date).slice(0, 10) : "",
  subject: $json.subject || "",
  body: text.slice(0, 6000),
  account_id: user.account_id,
  account_holder: user.account_holder,
};
const amountPattern = /(\d+(?:[.,]\d{3})*(?:[.,]\d{1,2})?\s?(EUR|€|Euro))|((EUR|€)\s?\d+(?:[.,]\d{1,2})?)/i;
email.has_amount = amountPattern.test(email.subject + " " + email.body);
if (!email.has_amount) return null;
return { json: email };

