let text = String($json.output ?? "").trim()
  .replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
const start = text.indexOf("{");
let parsed = null;
if (start >= 0) {
  // Try the longest JSON first; if a stray "}" breaks it, try a shorter end
  for (let end = text.lastIndexOf("}"); end > start; end = text.lastIndexOf("}", end - 1)) {
    try { parsed = JSON.parse(text.slice(start, end + 1)); break; } catch (e) {}
  }
}
if (parsed && typeof parsed.output === "object") parsed = parsed.output;   // unwrap if wrapped
if (!parsed) {
  parsed = { type: "uncertain", category: "other", needs_attention: true, reason: "unreadable_answer" };
}
return { json: { result: parsed } };
